{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title",
        "intro_text",
        "principles_heading",
        "principle_1_stack",
        "principle_2_stack",
        "principle_3_stack",
        "principle_4_stack",
        "principle_5_stack",
        "principle_6_stack",
        "principle_7_stack",
        "resources_heading",
        "resource_1_button",
        "resource_2_button"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Crafting User-Centric Productivity Notifications",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Designing effective and non-intrusive notifications is crucial for productivity applications to enhance user engagement without causing distraction or fatigue. The goal is to deliver timely, relevant information that empowers users to act efficiently.",
        "variant": "body"
      },
      "children": []
    },
    "principles_heading": {
      "type": "Text",
      "props": {
        "text": "Key Principles for Non-Intrusive Notifications",
        "variant": "h3"
      },
      "children": []
    },
    "principle_1_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "principle_1_header",
        "principle_1_impl"
      ]
    },
    "principle_1_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "principle_1_icon",
        "principle_1_title"
      ]
    },
    "principle_1_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000120_01_1_signpost-split.svg"
      },
      "children": []
    },
    "principle_1_title": {
      "type": "Text",
      "props": {
        "text": "Contextual Relevance",
        "variant": "body"
      },
      "children": []
    },
    "principle_1_impl": {
      "type": "Text",
      "props": {
        "text": "Utilize smart algorithms to identify critical moments (e.g., deadline approaching for an active project, collaborator comment on a shared document you're currently viewing). Avoid generic, untargeted alerts.",
        "variant": "body"
      },
      "children": []
    },
    "principle_2_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "principle_2_header",
        "principle_2_impl"
      ]
    },
    "principle_2_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "principle_2_icon",
        "principle_2_title"
      ]
    },
    "principle_2_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000120_01_2_sliders.svg"
      },
      "children": []
    },
    "principle_2_title": {
      "type": "Text",
      "props": {
        "text": "User Control & Customization",
        "variant": "body"
      },
      "children": []
    },
    "principle_2_impl": {
      "type": "Text",
      "props": {
        "text": "Offer granular settings (e.g., \"Notify me for comments on my tasks,\" \"Only urgent tasks,\" \"Daily digest at 9 AM\"). Provide seamless integration with \"Do Not Disturb\" or \"Focus Mode\" features.",
        "variant": "body"
      },
      "children": []
    },
    "principle_3_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "principle_3_header",
        "principle_3_impl"
      ]
    },
    "principle_3_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "principle_3_icon",
        "principle_3_title"
      ]
    },
    "principle_3_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000120_01_3_chat-text.svg"
      },
      "children": []
    },
    "principle_3_title": {
      "type": "Text",
      "props": {
        "text": "Clear & Concise Messaging",
        "variant": "body"
      },
      "children": []
    },
    "principle_3_impl": {
      "type": "Text",
      "props": {
        "text": "Avoid jargon or lengthy explanations. State the action or information clearly. Example: \"Task 'Project X' due tomorrow\" instead of \"Attention: Project X deadline imminent.\"",
        "variant": "body"
      },
      "children": []
    },
    "principle_4_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "principle_4_header",
        "principle_4_impl"
      ]
    },
    "principle_4_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "principle_4_icon",
        "principle_4_title"
      ]
    },
    "principle_4_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000120_01_4_cursor.svg"
      },
      "children": []
    },
    "principle_4_title": {
      "type": "Text",
      "props": {
        "text": "Actionability & Next Steps",
        "variant": "body"
      },
      "children": []
    },
    "principle_4_impl": {
      "type": "Text",
      "props": {
        "text": "Use actionable buttons like \"Complete Task,\" \"Reply,\" or \"View Details.\" Minimize the number of steps required for the user to respond or access the related content.",
        "variant": "body"
      },
      "children": []
    },
    "principle_5_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "principle_5_header",
        "principle_5_impl"
      ]
    },
    "principle_5_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "principle_5_icon",
        "principle_5_title"
      ]
    },
    "principle_5_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000115_01_1_clock.svg"
      },
      "children": []
    },
    "principle_5_title": {
      "type": "Text",
      "props": {
        "text": "Timing & Frequency Optimization",
        "variant": "body"
      },
      "children": []
    },
    "principle_5_impl": {
      "type": "Text",
      "props": {
        "text": "Allow users to set preferred delivery times for daily or weekly digests. Employ intelligent throttling to prevent rapid-fire alerts for similar events.",
        "variant": "body"
      },
      "children": []
    },
    "principle_6_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "principle_6_header",
        "principle_6_impl"
      ]
    },
    "principle_6_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "principle_6_icon",
        "principle_6_title"
      ]
    },
    "principle_6_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000118_01_5_bell.svg"
      },
      "children": []
    },
    "principle_6_title": {
      "type": "Text",
      "props": {
        "text": "Gradual Intrusion & Feedback",
        "variant": "body"
      },
      "children": []
    },
    "principle_6_impl": {
      "type": "Text",
      "props": {
        "text": "Visual badge updates -> subtle sound -> brief pop-up. Ensure a clear visual or auditory confirmation when a notification is dismissed or acted upon.",
        "variant": "body"
      },
      "children": []
    },
    "principle_7_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "principle_7_header",
        "principle_7_impl"
      ]
    },
    "principle_7_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "principle_7_icon",
        "principle_7_title"
      ]
    },
    "principle_7_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000120_01_7_window.svg"
      },
      "children": []
    },
    "principle_7_title": {
      "type": "Text",
      "props": {
        "text": "Platform Consistency",
        "variant": "body"
      },
      "children": []
    },
    "principle_7_impl": {
      "type": "Text",
      "props": {
        "text": "Utilize native notification styles and behaviors where appropriate, respecting system-wide \"Do Not Disturb\" settings and user preferences.",
        "variant": "body"
      },
      "children": []
    },
    "resources_heading": {
      "type": "Text",
      "props": {
        "text": "Further Reading & Resources",
        "variant": "h3"
      },
      "children": []
    },
    "resource_1_button": {
      "type": "Button",
      "props": {
        "label": "Google Material Design - Notifications"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://m2.material.io/design/communication/notifications.html"
          }
        }
      },
      "children": []
    },
    "resource_2_button": {
      "type": "Button",
      "props": {
        "label": "Nielsen Norman Group - Notifications UX"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.nngroup.com/articles/notifications-ux/"
          }
        }
      },
      "children": []
    }
  }
}
